    \tilde p_i^{hard}
    =
    \frac{\exp(z_i)}{\sum_{j\in\mathcal{S}}\exp(z_j)}
    \le
    \exp\!\left(z_i-\max_{j\in\mathcal{S}}z_j\right).
    \label{eq:rank_unbounded}
\end{equation}

